name: Remove SLO label after SLO workflow

on:
  pull_request_target:
    types: [opened, synchronize, reopened, closed]

permissions:
  contents: read
  issues: write

jobs:
  check-slo-workflow:
    runs-on: ubuntu-latest
    outputs:
      slo_completed: ${{ steps.check.outputs.slo_completed }}
    steps:
      - name: Check SLO workflow status
        id: check
        uses: actions/github-script@v7
        with:
          script: |
            const pr = context.payload.pull_request;
            if (!pr) {
              core.setOutput('slo_completed', 'false');
              return;
            }
            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const workflowName = 'SLO';
            // Get the workflow ID
            const workflows = await github.rest.actions.listRepoWorkflows({owner, repo});
            const workflow = workflows.data.workflows.find(w => w.name === workflowName);
            if (!workflow) {
              core.setOutput('slo_completed', 'false');
              return;
            }
            const workflowId = workflow.id;
            // List recent runs for this workflow on the PR branch
            const runs = await github.rest.actions.listWorkflowRuns({
              owner,
              repo,
              workflow_id: workflowId,
              head_branch: pr.head.ref,
              per_page: 1
            });
            const latestRun = runs.data.workflow_runs[0];
            if (!latestRun) {
              core.setOutput('slo_completed', 'false');
              return;
            }
            const conclusion = latestRun.conclusion;
            core.setOutput('slo_completed', conclusion === 'success' || conclusion === 'failure' ? 'true' : 'false');
      - name: Debug
        run: echo "SLO completed: ${{ steps.check.outputs.slo_completed }}"

  remove-slo-label:
    needs: check-slo-workflow
    if: ${{ needs.check-slo-workflow.outputs.slo_completed == 'true' }}
    runs-on: ubuntu-latest
    steps:
      - name: Remove SLO label
        uses: actions/github-script@v7
        with:
          script: |
            const pr = context.payload.pull_request;
            if (!pr) {
              console.log('No pull request found in event payload.');
              return;
            }
            const label = 'SLO';
            try {
              await github.rest.issues.removeLabel({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: pr.number,
                name: label
              });
              console.log(`Removed label ${label} from PR #${pr.number}`);
            } catch (error) {
              if (error.status === 404) {
                console.log(`Label ${label} not found on PR #${pr.number}`);
              } else {
                throw error;
              }
            }
